#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {
 internal static class InternalPreviewTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MainWindow main=null;Window viewer=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};try{
   SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));FluentTheme.Ensure();
   string file=Path.Combine(root,"Example.xls");File.WriteAllText(file,"<?xml version=\"1.0\"?><Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\" xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\"><Worksheet ss:Name=\"Demo\"><Table><Row><Cell><Data ss:Type=\"String\">Product</Data></Cell><Cell><Data ss:Type=\"String\">Count</Data></Cell></Row><Row><Cell><Data ss:Type=\"String\">Example</Data></Cell><Cell><Data ss:Type=\"Number\">12</Data></Cell></Row></Table></Worksheet></Workbook>");
   main=new MainWindow(root,new ProgramSettings{AutoRefresh=false,InternalCodePreview=false}){Left=-18000,Top=-18000,ShowInTaskbar=false,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};main.Show();NavigationTests.WaitPanels(main);
   var panel=FluentUiTests.Children<FilePanel>(main).First();panel.Navigate(root,false);NavigationTests.Wait(panel.NavigationTask);var entry=panel.List.Items.Cast<Entry>().First(x=>String.Equals(x.FullPath,file,StringComparison.OrdinalIgnoreCase));panel.SelectContextEntry(entry);
   var menu=panel.List.ContextMenu;menu.RaiseEvent(new RoutedEventArgs(ContextMenu.OpenedEvent));var preview=menu.Items.OfType<MenuItem>().Single(x=>Convert.ToString(x.Tag)=="context.preview");check(preview.IsEnabled,"XLS context preview is enabled");preview.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));var pane=(QuickPreviewPane)typeof(MainWindow).GetField("quickPreview",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(main);check(pane!=null&&pane.IsVisible&&!main.OwnedWindows.Cast<Window>().Any(x=>x.Content is QuickPreviewPane),"XLS context preview opens inside the opposite panel without a popup");NavigationTests.Wait(pane.LoadingTask);NavigationTests.Wait(pane.MetadataLoadingTask);NavigationTests.Wait(pane.DocumentLoadingTask);check(DocumentPreview.Supports(file),"XLS is handled by embedded document rendering");
   if(DocumentPreview.Available()){var document=FluentUiTests.Children<DocumentPreview>(pane).SingleOrDefault();check(document!=null,"XLS preview uses the embedded document renderer");var web=FluentUiTests.Children<Microsoft.Web.WebView2.Wpf.WebView2>(document).Single();var script=web.ExecuteScriptAsync("document.body.innerText");NavigationTests.Wait(script);check(script.Result.Contains("Product")&&script.Result.Contains("Example")&&script.Result.Contains("12"),"Spreadsheet cells render inside the application");}
   NextStageTests.Draw(main,Path.Combine(root,"xls-preview.png"));panel.ViewSelected();check(Object.ReferenceEquals(pane,typeof(MainWindow).GetField("quickPreview",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(main))&&pane.IsVisible,"Repeated F3 refreshes the same opposite-panel preview");main.CloseQuickPreview();check(!pane.IsVisible,"Closing panel preview restores the original file panel");
   var baseIcon=DesktopIcons.StockIcon(8);check(Object.ReferenceEquals(baseIcon,DesktopIcons.DriveBadge(baseIcon,false,false)),"Ordinary drive retains its system icon");var usb=DesktopIcons.DriveBadge(baseIcon,true,false);var ext=DesktopIcons.DriveBadge(baseIcon,false,true);var both=DesktopIcons.DriveBadge(baseIcon,true,true);check(usb.IsFrozen&&ext.IsFrozen&&both.IsFrozen&&!Object.ReferenceEquals(usb,ext)&&!Object.ReferenceEquals(ext,both),"External, EXT and combined overlays are frozen and distinct");check(Object.ReferenceEquals(usb,DesktopIcons.DriveBadge(baseIcon,true,false)),"Drive overlays reuse cached images");int opened=0;panel.HoldCompletedForTests=delegate{opened++;};panel.StartRightHoldIndicator(new Point(15,15));check(!panel.RightHoldIndicatorOpen,"Initial right click does not show hold feedback");panel.AdvanceRightHold(TimeSpan.FromMilliseconds(200),true);check(!panel.RightHoldIndicatorOpen&&opened==0,"Short press stays free of hold feedback");panel.AdvanceRightHold(TimeSpan.FromMilliseconds(425),true);check(panel.RightHoldIndicatorOpen&&Math.Abs(panel.RightHoldProgress-.5)<.01&&opened==0,"Hold indicator fills halfway without opening a menu");panel.AdvanceRightHold(TimeSpan.FromMilliseconds(600),true);check(!panel.RightHoldIndicatorOpen&&opened==1,"Full hold opens the program menu immediately before release");panel.AdvanceRightHold(TimeSpan.FromMilliseconds(700),true);check(opened==1,"Long press opens only one menu");panel.StartRightHoldIndicator(new Point(15,15));panel.AdvanceRightHold(TimeSpan.FromMilliseconds(200),false);check(!panel.RightHoldIndicatorOpen&&opened==1,"Early release closes the indicator without opening the program menu");panel.CancelFileContextGesture();panel.StartRightHoldIndicator(new Point(15,15));panel.CancelFileContextGesture();check(!panel.RightHoldIndicatorOpen,"Cancellation or dragging removes hold feedback");panel.HoldCompletedForTests=null;
   check(Object.ReferenceEquals(DesktopIcons.FlashDriveIcon,DesktopIcons.StockIcon(7)),"Flash drive uses the native Windows removable-drive icon");check(!Object.ReferenceEquals(DesktopIcons.FlashDriveIcon,DesktopIcons.StockIcon(8)),"Removable-drive icon is distinct from fixed drive icon");main.Close();main=null;File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(viewer!=null)viewer.Close();if(main!=null)main.Close();}}
 }
}
#endif
